  /** Who this portal account may write to (search by name / number). */
  function chatDirectory(kind, row, cm, q) {
    const pol = CHATR.policyOf(chatPolicyRaw()); const out = [];
    if (!pol.enabled) return out;
    const term = String(q || '').trim().toLowerCase();
    const hit = (...xs) => !term || xs.some(x => String(x || '').toLowerCase().includes(term));
    const campusOk = (r) => !cm.me.campus_id || !r.campus_id || r.campus_id === cm.me.campus_id;
    const desks = kind === 'student' ? CHATR.STUDENT_DESKS : kind === 'parent' ? (pol.parents_to_desks ? CHATR.PARENT_DESKS : []) : Object.keys(CHATR.DESKS);
    for (const r of desks) if (hit(CHATR.DESKS[r])) out.push({ key: 'r:' + r, name: CHATR.DESKS[r], sub: 'Office desk', kind: 'desk' });
    if (kind === 'student' && pol.students_to_heads) {
      const fac = cm.me.faculty_id || null;
      for (const us of all('users')) {
        if (!us || Number(us.deleted) || (us.is_active != null && Number(us.is_active) === 0)) continue;
        const mine = (us.role === 'hod' && us.department_id && us.department_id === row.department_id) || (us.role === 'dean' && us.faculty_id && us.faculty_id === fac);
        if (!mine || !campusOk(us) || !hit(us.full_name, us.username, us.role === 'hod' ? 'head of department hod' : 'dean')) continue;
        out.push({ key: 'u:' + us.id, name: us.full_name || us.username, sub: us.role === 'hod' ? 'Your Head of Department' : 'Your Dean', kind: 'staff' });
      }
    }
    if (kind === 'parent') return out;
    if (kind !== 'student') {
      for (const u of all('users')) { if (out.length > 60) break; if (Number(u.deleted) || (u.is_active != null && Number(u.is_active) === 0) || cm.keys.includes('u:' + u.id) || !campusOk(u) || !hit(u.full_name, u.username)) continue; out.push({ key: 'u:' + u.id, name: u.full_name || u.username, sub: CHATR.DESKS[u.role] || u.role || 'Officer', kind: 'officer' }); }
    }
    if (kind !== 'student' || pol.students_to_lecturers) {
      for (const s of all('staff')) {
        if (out.length > 90) break;
        if (Number(s.deleted) || (s.is_active != null && Number(s.is_active) === 0) || cm.keys.includes('st:' + s.id) || !campusOk(s)) continue;
        if (kind === 'student' && s.staff_type !== 'lecturer') continue;
        if (!hit(s.full_name, s.staff_no, s.department)) continue;
        out.push({ key: 'st:' + s.id, name: s.full_name, sub: (s.staff_type === 'lecturer' ? 'Lecturer' : 'Staff') + (s.department ? ' · ' + s.department : ''), kind: 'staff' });
      }
    }
    const studentsOk = kind === 'user' || (kind === 'staff' && pol.staff_to_students) || (kind === 'student' && pol.students_peer);
    if (studentsOk && (term.length >= 2 || kind === 'student')) {
      for (const s of all('students')) {
        if (out.length > 120) break;
        if (Number(s.deleted) || s.id === row.id || !campusOk(s)) continue;
        if (kind === 'student' && (s.department_id !== row.department_id || (row.level_id && s.level_id !== row.level_id) || s.status === 'alumni')) continue;
        if (!hit(s.first_name, s.last_name, s.middle_name, s.matric_no)) continue;
        out.push({ key: 's:' + s.id, name: studentFullName(s), sub: kind === 'student' ? 'Classmate' : ('Student' + (s.matric_no ? ' · ' + s.matric_no : '')), kind: 'student' });
      }
    }
    return out.slice(0, 120);
  }
