      type: type.key, title: type.name, fields: JSON.stringify(fields), target_department_id: type.key === 'change_programme' ? fields.to_department_id : null, status: 'submitted', steps: JSON.stringify(RQ.initialSteps(type)), warnings: JSON.stringify(pc.warnings), messages: '[]',
