    const oh = officeHoursFor(s).find(o => o.id === (body && body.office_hour_id));
    if (!oh) return { ok: false, error: 'Those office hours are not open to you.' };
    const appts = all('appointments').filter(a => !a.deleted);
    const slot = { date: String((body && body.date) || ''), start: String((body && body.start) || '') };
    const errs = AR.checkBooking(oh, slot, { now: apptNow(), bookings: appts.filter(a => a.office_hour_id === oh.id), mine: appts.filter(a => a.student_id === s.id) });
    if (errs.length) return { ok: false, error: errs[0] };
