    const nowIso = new Date().toISOString(); const name = ((s.first_name || '') + ' ' + (s.last_name || '')).trim();
    const row = { id: crypto.randomUUID(), office_hour_id: oh.id, host_type: oh.host_type, host_id: oh.host_id, host_name: oh.host_name, student_id: s.id, student_name: name,
      date: slot.date, start_time: slot.start, end_time: end, topic: String((body && body.topic) || '').slice(0, 300), status: 'booked', created_at: nowIso, updated_at: nowIso, deleted: 0, origin_node: 'portal' };
    create('appointments', row);
