    const pays = studentPaymentsCompleted(s.id).filter(x => !Number(x.deleted));
    for (const x of pays) { const k = x.category + '|' + curOf(x.currency); paid[k] = (paid[k] || 0) + (Number(x.amount) || 0); }
    const totals = {}; const T = (cur) => totals[cur] || (totals[cur] = { currency: cur, billed: 0, paid: 0, owed: 0, confirming: 0, credit: 0 });
