        const body = { items: o.items, currency: o.currency, provider: pm ? pm.id : undefined, mode: o.mode === 'transfer' ? 'transfer' : undefined, phone: o.mode === 'push' ? phone : undefined, confirm_duplicate: !!o.confirm_duplicate };
        const rel = ussdRelation(st, phone);
