      res.writeHead(200, { 'Content-Type': 'application/javascript; charset=utf-8', 'Cache-Control': u.searchParams.get('v') === pk.v ? 'public, max-age=31536000, immutable' : 'no-cache', ...SEC_HEADERS });
      res.end(pk.js); return true;
