        return { id: c.id, title: c.title, description: c.description || '', goal: Number(c.goal_amount) || 0, currency: c.currency || 'NGN', raised: Math.round(raised * 100) / 100, gifts, featured: !!c.featured, ends_at: c.ends_at || null };
