        create('donations', donation);
        createIntent({ reference: r.reference || reference, provider, provider_ref: r.provider_ref || r.reference || reference, category: 'donation', amount, currency, test_mode: paymentsTestMode(), ip: (req.headers['x-forwarded-for'] || (req.socket && req.socket.remoteAddress) || '') });
