        const v = DEFR.validateTopics(b.topics); if (!v.ok) return fail(v.error);
        const keyOf = (xs) => xs.map(x => String(x.title || '').trim().toLowerCase()).sort().join('|');
        const open = all('project_topics').filter(x => alive(x) && x.student_id === s.id && x.status === 'proposed');
        if (open.length && keyOf(open) === keyOf(v.topics)) return done({ ids: open.map(x => x.id), already: true });
        const who = (id) => { const x = one('students', id); return x ? [x.first_name, x.last_name].filter(Boolean).join(' ') + (x.matric_no ? ' (' + x.matric_no + ')' : '') : ''; };
        const pool = all('theses').filter(x => alive(x) && x.student_id !== s.id).map(x => ({ id: x.id, kind: 'project', title: x.title, who: who(x.student_id), year: String(x.start_date || '').slice(0, 4) }))
          .concat(all('project_topics').filter(x => alive(x) && x.student_id !== s.id && ['proposed', 'approved'].includes(x.status) && !x.thesis_id).map(x => ({ id: x.id, kind: 'proposal', title: x.title, who: who(x.student_id), year: String(x.created_at || '').slice(0, 4) })));
        for (const old of all('project_topics').filter(x => alive(x) && x.student_id === s.id && x.status === 'proposed')) update('project_topics', old.id, { status: 'withdrawn' });
        const ids = [];
        for (const tp of v.topics) {
          const id = crypto.randomUUID(); ids.push(id);
          const sim = DEFR.similarTopics(tp.title, pool).map(x => ({ id: x.id, kind: x.kind, title: x.title, who: x.who, year: x.year, score: x.score, level: x.level }));
          create('project_topics', { id, student_id: s.id, department_id: s.department_id || null, programme: 'Project', title: tp.title, summary: tp.summary || null, rank: tp.rank, status: 'proposed', similar: JSON.stringify(sim), via: b.via === 'app' ? 'app' : 'portal', campus_id: s.campus_id || null, created_at: nowIso(), updated_at: nowIso(), deleted: 0, origin_node: 'portal' });
        }
