  if(tpv)provHtml+='<label style="display:flex;align-items:center;gap:10px;padding:11px 12px;border:1px solid #bbf7d0;background:#f0fdf4;border-radius:10px;margin-bottom:8px;cursor:pointer"><input type="radio" name="payprov" value="'+eh(tpv.id)+'" data-mode="transfer"'+(providers.length===0?' checked':'')+'><span><span style="font-weight:600">🏦 Bank transfer — confirmed automatically</span><br><span class="muted" style="font-size:11.5px">From any bank app or USSD · no receipt to upload</span></span></label>';
  ov.innerHTML='<div style="background:#fff;border-radius:16px;max-width:430px;width:100%;padding:20px;box-shadow:0 24px 60px rgba(2,6,23,.4)">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px"><h3 style="margin:0">💳 Pay '+eh(single?cap(category):(items.length+' fees'))+'</h3><span id="payX" style="cursor:pointer;font-size:22px;color:#64748b">×</span></div>'
    +'<div class="muted" style="font-size:13px;margin-bottom:12px">'+(single?'Outstanding':'Selected')+': <b>'+money(outstanding,currency)+'</b></div>'
    +(single?'':'<div style="font-size:13px;margin-bottom:8px">'+items.map(function(x){return '<div style="display:flex;justify-content:space-between;padding:3px 0;border-bottom:1px solid #f1f5f9"><span>'+eh(cap(x.category))+'</span><b>'+money(x.amount,currency)+'</b></div>';}).join('')+'</div>')
    +'<label style="font-size:12px;color:#64748b">'+(single?'Amount to pay':'Total')+' ('+eh(currency)+')</label>'
    +'<input id="payAmt" type="number" min="1" step="0.01" max="'+Number(outstanding)+'" value="'+Number(outstanding)+'"'+(single?'':' readonly')+' style="width:100%;border:1px solid #cbd5e1;border-radius:10px;padding:10px;margin:4px 0 14px;font-size:15px;box-sizing:border-box">'
    +(providers.length?'<div style="font-size:12px;color:#64748b;margin-bottom:6px">Choose a payment method</div>':'')+provHtml
    +(single&&items[0].autopay_ok?'<label id="payAPBox" style="display:none;align-items:flex-start;gap:8px;margin-top:8px;padding:10px;border:1px solid #c7d2fe;background:#eef2ff;border-radius:10px;font-size:13px;cursor:pointer"><input type="checkbox" id="payAP" style="width:auto;flex:none;margin-top:2px"><span><b>🔁 Pay my next installments automatically from this card</b><br><span class="muted" style="font-size:11.5px">You are told 3 days before each one and can turn it off any time on Fees. We never see the card number.</span></span></label>':'')
    +'<div id="payPhoneBox" style="display:none;margin-top:6px"><label style="font-size:12px;color:#64748b" for="payPhone">Phone number for the payment prompt</label><input id="payPhone" type="tel" autocomplete="tel" placeholder="e.g. 0712 345 678" style="width:100%;border:1px solid #cbd5e1;border-radius:10px;padding:10px;margin:4px 0 6px;box-sizing:border-box"></div>'
    +'<div id="payErr" style="color:#b91c1c;font-size:13px;margin-top:6px" role="alert"></div><div id="payAlt"></div>'
    +'<button id="payGo" class="btn full" style="margin-top:12px">Pay now</button>'
    +'<button id="payBank" class="btn full ghost" style="margin-top:8px;background:#fff;color:#1e3a8a;border:1px solid #cbd5e1">🏦 Pay by bank transfer instead</button>'
    +'<div id="payManual" style="margin-top:10px"></div>'
    +'<div class="muted" style="font-size:11px;margin-top:10px;text-align:center">🔒 Payments are processed securely by the gateway. We never see your card details.</div></div>';
  document.body.appendChild(ov);
  function close(){try{document.body.removeChild(ov);}catch(_){}}
  ov.querySelector('#payX').onclick=close;
  ov.addEventListener('click',function(e){if(e.target===ov)close();});
  // 🏦 manual bank transfer: bank details + claim form (payer, bank, date, reference, receipt upload).
