async function wbCancel(id){if(!confirm('Cancel this counselling request?'))return;var r=await campusPost('/api/wellbeing/counselling/cancel',{id:id},'Cancelled.');if(!r.ok)alert(r.error);}
async function clRsvp(id,going){var r=await campusPost('/api/campus/rsvp',{event_id:id,going:going},going?'See you there!':'RSVP cancelled.');if(!r.ok)alert(r.error);}
async function clClub(id,join){if(!join&&!confirm('Leave this club?'))return;var r=await campusPost('/api/campus/club',{club_id:id,join:join},join?'Done.':'You left the club.');if(!r.ok)alert(r.error);}
function trRequest(rid){var r=((CAMPUS.transport||{}).routes||[]).find(function(x){return x.id===rid;})||{};var st=(r.stops||[]).map(function(s){return [s,s];});
  cform('Request a seat — '+(r.name||''),st.length?[{name:'stop',label:'Where will you board?',type:'select',options:st}]:[],function(v){return campusPost('/api/transport/request',{route_id:rid,stop:v.stop||''},'Request sent to the transport office.');},'Request');}
async function trCancel(id){if(!confirm('Withdraw this request?'))return;var r=await campusPost('/api/transport/cancel',{id:id},'Withdrawn.');if(!r.ok)alert(r.error);}
