      +'<div class="muted" style="font-size:13px;margin:4px 0 10px">'+eh(String(g.ceremony_at||'').replace('T',' '))+(g.venue?' · '+eh(g.venue):'')+(g.rsvp_deadline?' · reply by '+eh(g.rsvp_deadline):'')+'</div>'
      +(g.notes?'<div style="font-size:13px;white-space:pre-wrap;margin-bottom:10px">'+eh(g.notes)+'</div>':'')
