    +'.msg-b .w{font-size:11px;font-weight:700;color:var(--brand);margin-bottom:2px}.msg-b .a{font-size:10.5px;color:var(--muted);text-align:right;margin-top:3px}'
    +'.msg-comp{display:flex;gap:8px;padding:10px;border-top:1px solid var(--line);align-items:flex-end}.msg-comp textarea{flex:1;resize:none;min-height:42px;max-height:140px}'
