    +'.msg-b .a a{color:var(--muted);text-decoration:none;margin-left:4px}.msg-call{text-align:center;align-self:center;max-width:90%}'
    +'.msg-pick{display:flex;gap:4px;margin-top:4px}.msg-pick span{font-size:18px;cursor:pointer;padding:2px}'
    +'.msg-rep{display:flex;gap:8px;align-items:center;padding:6px 12px;border-top:1px solid var(--line);font-size:12.5px;background:rgba(var(--brand-rgb),.06)}.msg-rep div{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}'
    +'.msg-typ{font-size:11.5px;color:var(--brand);padding:2px 12px;min-height:16px}.btn.rec{background:#dc2626;color:#fff}'
    +'.call-ov{position:fixed;inset:0;background:rgba(15,23,42,.72);z-index:9998;display:flex;align-items:center;justify-content:center;padding:16px}'
    +'.call-card{background:var(--card);color:var(--text);border-radius:20px;padding:26px 22px;width:min(360px,100%);text-align:center;box-shadow:0 20px 50px rgba(0,0,0,.35)}'
    +'.call-card .who{font-size:20px;font-weight:800;margin:8px 0 2px}.call-card .row{display:flex;gap:14px;justify-content:center;margin-top:18px}'
