  var q=ov.querySelector('#mp-q'),res=ov.querySelector('#mp-res'),chips=ov.querySelector('#mp-chips');
  var IC={desk:'🏢',officer:'🧑‍💼',staff:'🧑‍🏫',student:'🎓'};
