// 📝 the brief (headline + points) — written from the figures, the same words as the desk
var OR_BT={good:'#16a34a',warn:'#d97706',bad:'#dc2626',info:'#64748b'},OR_BI={good:'✅',warn:'⚠️',bad:'❗',info:'•'};
function orBrief(br){if(!br||!br.points||!br.points.length)return '';return '<div style="border-left:4px solid '+(OR_BT[br.tone]||OR_BT.info)+';background:#f8fafc;border-radius:10px;padding:10px 12px;margin-bottom:10px"><div class="muted" style="font-size:11px;text-transform:uppercase;letter-spacing:.5px">📝 In brief</div><div style="font-weight:700;margin:3px 0 6px">'+eh(br.headline)+'</div>'+br.points.map(function(x){return '<div style="font-size:12.5px;margin:2px 0">'+(OR_BI[x.tone]||'•')+' '+eh(x.text)+'</div>';}).join('')+'</div>';}
// 🎯 collection targets (progress bar + pace marker) · 📞 log a follow-up with a student who owes
var OR_TS={met:['met','#16a34a'],on_track:['on track','#2563eb'],behind:['behind','#d97706'],missed:['missed','#dc2626'],no_billing:['nothing billed','#64748b']};
function orTargets(list){if(!list||!list.length)return '';return '<div style="margin-bottom:10px">'+list.map(function(x){var pc=function(v){return v==null?'—':Math.round(v*1000)/10+'%';};var w=Math.min(100,(x.rate||0)/x.target_pct*100),e2=Math.min(100,x.expected/x.target_pct*100),st=OR_TS[x.state]||OR_TS.behind;
  return '<div style="margin:6px 0"><div style="display:flex;justify-content:space-between;gap:6px;flex-wrap:wrap;font-size:13px"><span>🎯 <b>'+eh(x.scope_name)+'</b> · '+pc(x.target_pct)+' by '+eh(x.due_date)+' ('+eh(x.currency)+')</span><span style="color:'+st[1]+';font-weight:700">'+st[0]+'</span></div>'
   +'<div style="position:relative;height:9px;border-radius:5px;background:#e2e8f0;margin-top:3px"><div style="width:'+w+'%;height:100%;border-radius:5px;background:'+st[1]+'"></div><div style="position:absolute;top:-3px;left:'+e2+'%;width:2px;height:15px;background:#334155"></div></div>'
   +'<div class="muted" style="font-size:11.5px">'+PI18N.t('Collected')+' '+pc(x.rate)+' · '+PI18N.t('pace needed now')+' '+pc(x.expected)+(x.to_collect?' · '+PI18N.t('still to collect')+' '+money(x.to_collect,x.currency):'')+'</div></div>';}).join('')+'</div>';}
