    var lst=(x&&x.list)||[];q('#or_list').innerHTML='<h4 style="margin:10px 0 4px">'+eh(L[pr[0]])+' ('+((x&&x.list_total)||0)+')</h4><div class="tscroll"><table><tbody>'+lst.map(function(s2,i){var owe=Object.keys(s2.money).filter(function(c){return s2.money[c].owing>0;});return '<tr><td><b>'+eh(s2.name)+'</b><div class="muted" style="font-size:11.5px">'+eh(s2.matric_no)+' · '+eh(s2.level)+(s2.phone?' · '+eh(s2.phone):'')+(s2.last_contact?' · last contact '+eh(s2.last_contact.date)+' ('+eh(s2.last_contact.outcome)+')':'')+'</div>'+(owe.length?'<a href="#" data-fu="'+i+'" style="font-size:12px">📞 Log a follow-up</a><div id="fu_'+i+'"></div>':'')+'</td><td class="r">'+Object.keys(s2.money).map(function(c){return money(s2.money[c].paid,c)+' / '+money(s2.money[c].billed,c);}).join('<br>')+'</td></tr>';}).join('')+'</tbody></table></div>';
